// Shared trip extraction + intent flags (Parse + CRM)
const AR_DIGITS = '٠١٢٣٤٥٦٧٨٩';

function arToEnDigits(s) {
  return String(s || '').replace(/[٠-٩]/g, (d) => String(AR_DIGITS.indexOf(d)));
}

function parseTripContext(history) {
  if (!history) return null;
  const h = arToEnDigits(history);
  const out = { destination: null, city: null, nights: null, adults: null, travel_dates: null, last_price: null, hotel: null, tour_days: null };

  if (/ألماتي|Almaty/i.test(h)) {
    out.destination = 'كازاخستان';
    out.city = 'Almaty';
  } else if (/مоск|Moscow/i.test(h)) {
    out.destination = 'روسيا';
    out.city = 'Moscow';
  } else if (/سانت|Saint Petersburg/i.test(h)) {
    out.destination = 'روسيا';
    out.city = 'Saint Petersburg';
  } else if (/سمرقند|Samarkand/i.test(h)) {
    out.destination = 'أوزبكستان';
    out.city = 'Samarkand';
  }

  const nightsM = h.match(/(\d+)\s*ليالي/);
  if (nightsM) out.nights = parseInt(nightsM[1], 10);

  if (/شخصين|شخصان/.test(history)) out.adults = 2;
  else {
    const paxM = h.match(/(\d+)\s*(?:شخص|أشخاص|كبار|بالغ)/);
    if (paxM) out.adults = parseInt(paxM[1], 10);
  }

  const dateM = h.match(/(\d{1,2})\s*(يناير|فبراير|مارس|أبril|ابril|مايو|يونيو|يوليو|أغسطس|سبتمبر|أكتوبر|نوفمبر|ديسمبر)\s*[–-]\s*(\d{1,2})\s*(يناير|فبراير|مارس|أبril|ابril|مايو|يونيو|يوليو|أغسطس|سبتمبر|أكتوبر|نوفمبر|ديسمبر)/i);
  if (dateM) out.travel_dates = `${dateM[1]} ${dateM[2]} – ${dateM[3]} ${dateM[4]}`;

  const hotelM =
    history.match(/أساسية\s*[—–-]\s*([^\n⭐💵]+?)(?:\s*⭐|$)/i) ||
    history.match(/1️⃣\s*[^\n—–-]+[—–-]\s*([^\n⭐💵]+?)(?:\s*⭐|$)/i);
  if (hotelM) out.hotel = hotelM[1].trim();

  const tourM = h.match(/(\d+)\s*أيام?\s*جولات/) || h.match(/(\d+)\s*جولات/);
  if (tourM) out.tour_days = parseInt(tourM[1], 10);

  const prices = [...h.matchAll(/(\d{3,4})\s*دولار/g)].map((m) => m[1]);
  if (prices.length) out.last_price = prices[prices.length - 1];

  if (!out.city && !out.nights && !out.adults) return null;
  return out;
}

function parseLeadNotes(notes) {
  const out = {};
  if (!notes) return out;
  for (const seg of String(notes).split(';')) {
    const i = seg.indexOf('=');
    if (i > 0) out[seg.slice(0, i).trim()] = seg.slice(i + 1).trim();
  }
  return out;
}

function mergeTripContext(fromHistory, fromNotes) {
  const trip = { ...(fromHistory || {}) };
  if (!fromNotes) return trip;
  if (fromNotes.city) trip.city = fromNotes.city;
  if (fromNotes.nights) trip.nights = parseInt(fromNotes.nights, 10);
  if (fromNotes.tour_days) trip.tour_days = parseInt(fromNotes.tour_days, 10);
  if (fromNotes.hotel) trip.hotel = fromNotes.hotel;
  if (fromNotes.last_price) trip.last_price = fromNotes.last_price;
  return trip;
}

function parseRequestedTourDays(text) {
  const t = arToEnDigits(text);
  let m = t.match(/(\d+)\s*(?:أيام?\s*جولات|جولات|جول)/);
  if (m) return parseInt(m[1], 10);
  if (/جولتين|جولين/.test(text)) return 2;
  if (/ثلاث(?:ة)?\s*جول/.test(text)) return 3;
  if (/أ?ربع\s*جول/.test(text)) return 4;
  if (/خمس\s*جول/.test(text)) return 5;
  if (/ست(?:ة)?\s*جول/.test(text)) return 6;
  return null;
}

function tripContextSummary(trip) {
  if (!trip) return '';
  const parts = [];
  if (trip.destination) parts.push('الوجهة: ' + trip.destination);
  if (trip.city) parts.push('المدينة: ' + trip.city);
  if (trip.travel_dates) parts.push('التواريخ: ' + trip.travel_dates);
  if (trip.nights != null) parts.push('الليالي: ' + trip.nights);
  if (trip.adults != null) parts.push('الكبار: ' + trip.adults);
  if (trip.last_price) parts.push('آخر سعر معروض: ' + trip.last_price + ' دولار');
  return parts.join(' | ');
}

const body = $input.first().json.body || $input.first().json;
const data = body.data || body;
const key = data.key || {};
const remoteJid = key.remoteJid || '';
const phone = remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '');

if (key.fromMe) return [];

const message = data.message || {};
const messageType = data.messageType || 'unknown';
let textContent = '';
if (messageType === 'conversation') textContent = message.conversation || '';
else if (messageType === 'extendedTextMessage') textContent = (message.extendedTextMessage || {}).text || '';
else if (messageType === 'audioMessage') textContent = '[رسالة صوتية]';
else textContent = message.conversation || message.text || '';

textContent = textContent.replace(/(\d+)\s*(ايام|أيام|يوم)/g, (m, d) => `${parseInt(d, 10) - 1} ليالي`);
textContent = textContent.replace(/اسبوعين|أسبوعين/g, '13 ليالي');
textContent = textContent.replace(/اسبوع|أسبوع/g, '7 ليالي');
textContent = textContent.replace(/عشر ايام|عشرة ايام|عشر أيام|عشرة أيام/g, '9 ليالي');
textContent = textContent.replace(/خمسة ايام|خمس ايام|خمسة أيام/g, '4 ليالي');
textContent = textContent.replace(/ستة ايام|ست ايام/g, '5 ليالي');

const MANAGER_PHONE = '380936582617';
const isManager = phone === MANAGER_PHONE;
const SB = String($env.SUPABASE_URL || 'https://xfibcjhshpmqkrhlpsoa.supabase.co').replace(/\/$/, '') + '/rest/v1';
const KEY = $env.SUPABASE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY;
if (!KEY) throw new Error('SUPABASE_KEY required');
const h = { apikey: KEY, Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' };

function leadHasStoredTrip(lead) {
  if (!lead) return false;
  return !!(lead.destination || lead.travel_dates || lead.pax_adults || lead.pax_children || lead.notes);
}

function buildLeadStateSummary(lead, tripCtx) {
  const parts = [];
  if (lead?.name) parts.push('الاسم: ' + lead.name);
  if (lead?.destination) parts.push('الوجهة: ' + lead.destination);
  else if (tripCtx?.destination) parts.push('الوجهة: ' + tripCtx.destination);
  if (lead?.travel_dates) parts.push('التواريخ: ' + lead.travel_dates);
  else if (tripCtx?.travel_dates) parts.push('التواريخ: ' + tripCtx.travel_dates);
  if (lead?.pax_adults != null) parts.push('الكبار: ' + lead.pax_adults);
  else if (tripCtx?.adults != null) parts.push('الكبار: ' + tripCtx.adults);
  if (lead?.pax_children != null) parts.push('الأطفال: ' + lead.pax_children);
  if (tripCtx?.nights != null) parts.push('الليالي: ' + tripCtx.nights);
  if (tripCtx?.tour_days != null) parts.push('أيام الجولات: ' + tripCtx.tour_days);
  if (tripCtx?.hotel) parts.push('الفندق: ' + tripCtx.hotel);
  if (tripCtx?.city) parts.push('المدينة: ' + tripCtx.city);
  if (tripCtx?.last_price) parts.push('آخر سعر: ' + tripCtx.last_price + ' دولار');
  if (lead?.stage) parts.push('المرحلة: ' + lead.stage);
  if (lead?.offer_sent) parts.push('تم إرسال عرض');
  if (lead?.notes) parts.push('ملاحظات: ' + String(lead.notes).slice(0, 200));
  return parts.join(' | ');
}

const trimmed = textContent.trim();
const returningRx = /(خبرتكم|خبرتك|قلت\s*لك|قلت\s*لنا|سبق\s*و|قبل\s*كذا|انا\s*خبرت|أنا\s*خبرت|from\s*before)/i;
const newTripRx = /^(جديد|بداية\s*جديدة|new\s*trip|رحلة\s*جديدة|من\s*الاول|من\s*الأول)/i;
const greetingRx = /^(السلام|سلام|مرحبا|هلا|أهلا|ياهلا|صباح|مساء|هلو|hello|hi\b)/i;
const hotelOnlyRx = /(فندق\s*فقط|فنادق\s*بس|فندق\s*بس|بس\s*فندق|احتاج\s*فندق|hotel\s*only|هذا\s*فنادق)/i;
const priceObjectionRx = /(غالي|غالية|سعركم|السعر\s*عالي|expensive|too\s*much|ارخص|أرخص)/i;
const goodbyeRx = /(لا\s*خلاص|خلاص\s*شكر|شكر\s*بس|ما\s*بغى|ما\s*ابغى|مو\s*مهتم|not\s*interested)/i;
const aiQuestionRx = /(موظف|موظفه|موظفة|إنسان|بشر|human|robot|روبوت|bot\b|ai\b|ذكاء\s*اصطناع|انت\s*ذكاء|أنت\s*ذكاء|انتي\s*موظف|أنتي\s*موظف)/i;
const driverLangRx = /(السواق|السائق|سائق|driver).*(عربي|arabic|يتكلم|يتحدث|speak)/i;
const opsFactRx = /(الغاء|إلغاء|cancellation|طريق[ةه]\s*الدفع|payment\s*method|مرافق|facility|policy)/i;
const tourModifyRx =
  /(?:خليها|خلها|خلي|ابي|أبي|اريد|أريد|ابغى|بغى|حط|خل)\s*(?:لي|ل)?\s*(?:\d+|جولتين|جولين|ثلاث|ثلاثة|أ?ربع|خمس|ست|ستة)(?:\s*(?:جول|جولات|أيام))?/i;
const tourFlexRx =
  /(?:المفترض|مفروض|يعني|6\s*جولات?\s*او|جولات?\s*او\s*كم|ينفع\s*ن|نقدر\s*ن(?:زيد|قلل|عدل)|ممكن\s*ن(?:زيد|قلل|عدل))/i;
const packageCompositionRx =
  /(ايش|كم|ويش|كيف|why).*(جول|جولات|tour|بكج|باقة|عرض|ليالي|ليال|ايام|أيام)|(?:البكج|الباقة|العرض)\s*(كيف|وش|ايش)|(?:عندي|عندنا)\s*\d+\s*(ليالي|ليال|ايام|أيام)|(?:this|the)\s*package/i;

const isReturningCustomer = returningRx.test(trimmed);
const isExplicitNewTrip = newTripRx.test(trimmed);
const isGreeting = greetingRx.test(trimmed);

let isNew = false;
let lead = null;
try {
  const r = await this.helpers.httpRequest({ method: 'GET', url: `${SB}/leads?phone=eq.${phone}&limit=1`, headers: h });
  if (r.length > 0) {
    lead = r[0];
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${SB}/leads?phone=eq.${phone}`,
      headers: { ...h, Prefer: 'return=minimal' },
      body: { last_contact: new Date().toISOString(), updated_at: new Date().toISOString() },
    });
  } else {
    isNew = true;
    if (!isManager) {
      const r2 = await this.helpers.httpRequest({
        method: 'POST',
        url: `${SB}/leads`,
        headers: { ...h, Prefer: 'return=representation' },
        body: { phone, stage: 'new', assigned_to: 'bot', source: 'direct', last_contact: new Date().toISOString() },
      });
      lead = r2[0] || null;
    }
  }
} catch (e) {}

if (!isManager) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${SB}/conversations`,
      headers: { ...h, Prefer: 'return=minimal' },
      body: { phone, role: 'user', message: textContent },
    });
  } catch (e) {}
}

const shouldResetLead = isExplicitNewTrip && phone && !isReturningCustomer;
if (shouldResetLead) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: SB + '/leads?phone=eq.' + phone,
      headers: { ...h, Prefer: 'return=minimal' },
      body: {
        stage: 'new',
        destination: null,
        travel_dates: null,
        pax_adults: null,
        pax_children: null,
        children_ages: null,
        offer_sent: false,
        notes: null,
        next_followup: null,
        follow_up_count: 0,
        objection_type: null,
        needs_human: false,
        updated_at: new Date().toISOString(),
      },
    });
    if (lead) {
      lead.stage = 'new';
      lead.destination = null;
      lead.travel_dates = null;
      lead.pax_adults = null;
    }
  } catch (e) {}
}

let chatHistory = '';
try {
  const msgs = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SB}/conversations?phone=eq.${phone}&order=id.asc&limit=30`,
    headers: h,
  });
  chatHistory = msgs.map((m) => (m.role === 'user' ? 'العميل' : 'ليلى') + ': ' + m.message).join('\n');
} catch (e) {}

const tripFromHistory = parseTripContext(chatHistory);
const tripCtx = mergeTripContext(tripFromHistory, parseLeadNotes(lead?.notes));
const requestedTourDays = parseRequestedTourDays(trimmed);
const hasModifyVerb = tourModifyRx.test(trimmed);

// Backfill lead CRM from chat when empty (root cause: quotes never persisted)
if (tripFromHistory && lead && !leadHasStoredTrip(lead) && phone && !isManager) {
  const patch = { updated_at: new Date().toISOString() };
  if (tripFromHistory.destination) patch.destination = tripFromHistory.destination;
  if (tripFromHistory.travel_dates) patch.travel_dates = tripFromHistory.travel_dates;
  if (tripFromHistory.adults != null) patch.pax_adults = tripFromHistory.adults;
  if (tripFromHistory.nights != null) patch.notes = `nights=${tripFromHistory.nights};city=${tripFromHistory.city || ''}`;
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${SB}/leads?phone=eq.${phone}`,
      headers: { ...h, Prefer: 'return=minimal' },
      body: patch,
    });
    Object.assign(lead, patch);
  } catch (e) {}
}

let managerInstructions = '';
try {
  const inst = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SB}/manager_instructions?active=eq.true&order=created_at.desc&limit=20`,
    headers: h,
  });
  if (inst.length > 0) managerInstructions = inst.map((i) => '- ' + i.instruction).join('\n');
} catch (e) {}

const leadStateSummary = buildLeadStateSummary(lead, tripCtx);
const hasTripContext = !!(leadStateSummary && !/^المرحلة:\s*new\s*$/.test(leadStateSummary));

let conversationIntent = 'general';
if (goodbyeRx.test(trimmed)) conversationIntent = 'goodbye';
else if (aiQuestionRx.test(trimmed)) conversationIntent = 'ai_identity';
else if (driverLangRx.test(trimmed) || (opsFactRx.test(trimmed) && !/طريق[ةه]\s*الدفع/.test(trimmed))) conversationIntent = 'ops_unknown';
else if (hotelOnlyRx.test(trimmed)) conversationIntent = 'hotel_only';
else if (priceObjectionRx.test(trimmed)) conversationIntent = 'price_objection';
else if (isReturningCustomer) conversationIntent = 'returning_customer';
else if (hasModifyVerb && requestedTourDays != null && tripCtx?.city) conversationIntent = 'package_tour_modify';
else if (tourFlexRx.test(trimmed) && /جول/.test(trimmed) && tripCtx?.city) conversationIntent = 'package_tour_flexibility';
else if (packageCompositionRx.test(trimmed) && tripCtx?.city) conversationIntent = 'package_composition';

const conversationHints = [];
if (conversationIntent === 'returning_customer' && hasTripContext) {
  conversationHints.push('استخدمي بيانات المحادثة/leadContext — لا تعيدي سؤال التفاصيل.');
}
if (conversationIntent === 'price_objection') {
  conversationHints.push('اعتراض سعر — استخدمي Pricing Engine فقط.');
}

let context = '';
if (isManager) context = 'هذا المدير أبو أمير — عامليه كمديرك.';
else if (isNew) context = 'عميل جديد — عرّفي نفسك باختصار «أنا ليلى من أركاديا» فقط إذا يلزم.';
else if (isReturningCustomer || hasTripContext) context = 'عميل سابق — لا تعرّفي نفسك ولا تسألي تفاصيل محفوظة.';
else if (isGreeting) context = 'تحية — ردّي باختصار واسألي فقط عن الناقص.';
else context = 'عميل سابق — لا تعرّفي نفسك.';
if (leadStateSummary) context += ' بيانات محفوظة: ' + leadStateSummary + '.';

const enWords = (textContent.match(/[a-zA-Z]{3,}/g) || []).length;
const totalWords = textContent.trim().split(/\s+/).length;
const customerLanguage = enWords / Math.max(totalWords, 1) > 0.5 ? 'en' : 'ar';

return [{
  json: {
    phone,
    remoteJid,
    textContent,
    customerLanguage,
    isManager,
    isNew,
    lead,
    leadStateSummary,
    tripFromHistory: tripCtx,
    requestedTourDays,
    chatHistory,
    managerInstructions,
    context,
    conversationHints,
    conversationIntent,
  },
}];

const de = $('Decision Engine').first()?.json || {};
const prev = { ...de, ...($input.first().json || {}) };
const SB = 'https://xfibcjhshpmqkrhlpsoa.supabase.co/rest/v1';
const KEY = 'REDACTED_SUPABASE_SERVICE_ROLE_KEY';
const h = { 'apikey':KEY, 'Authorization':'Bearer '+KEY, 'Content-Type':'application/json', 'Prefer':'return=minimal' };
if (!prev.isManager) {
  try { await this.helpers.httpRequest({ method:'POST', url:`${SB}/conversations`, headers:h, body:{ phone:prev.phone, role:'assistant', message:prev.response } }); } catch(e) {}
}
return [{ json: prev }];

// ========================================
// Cancel Follow-up on Client Reply
// أول Code node في Laila V4 (بعد Webhook)
// يستخدم this.helpers.httpRequest (لا fetch)
// ========================================

const SUPABASE_URL = 'https://xfibcjhshpmqkrhlpsoa.supabase.co';
const SUPABASE_KEY = 'REDACTED_SUPABASE_SERVICE_ROLE_KEY';

const raw     = $input.first().json;
const msgData = raw.data || raw;

// Defensive fromMe detection
const incomingPhone = msgData?.key?.remoteJid?.replace('@s.whatsapp.net', '');
const isFromBot     = msgData?.key?.fromMe === true || msgData?.message?.fromMe === true;

if (!incomingPhone || isFromBot) {
  return $input.all();
}

try {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/leads?phone=eq.${incomingPhone}`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation',
    },
    body: {
      next_followup: null,
      last_contact: new Date().toISOString(),
    },
    json: true,
  });
} catch(e) {
  // لا نوقف الـ flow لو الـ patch فشل
  console.log(`[CANCEL-FU] patch failed: ${e.message}`);
}

return $input.all();

// ========================================
// Set Follow-up — Smart Detection
// بعد "Send WhatsApp" في Laila V4
// يستخدم this.helpers.httpRequest (لا fetch)
// ========================================

const SUPABASE_URL = 'https://xfibcjhshpmqkrhlpsoa.supabase.co';
const SUPABASE_KEY = 'REDACTED_SUPABASE_SERVICE_ROLE_KEY';

const ctx    = $input.first().json;
const phone  = ctx.phone
  || ctx.data?.key?.remoteJid?.replace('@s.whatsapp.net', '')
  || ctx.from;

const botMsg      = ctx.botMessage || ctx.finalResponse || ctx.message || '';
const destination = ctx.destination || ctx.context?.destination || null;
const name        = ctx.name || ctx.clientName || null;

if (!phone) return $input.all();

// Price Detection
const PRICE_PATTERNS = [
  /\$[\d,]+/, /USD\s*[\d,]+/i,
  /[\d,]{3,}\s*(دولار|ريال|درهم)/,
  /السعر[:\s]+/, /🥇|🥈|🥉/,
  /الاقتصادي|الفاخر|المتوسط/,
  /ليلة.*\$/,
];

const hasPriceSent = PRICE_PATTERNS.some(p => p.test(botMsg));
if (!hasPriceSent) return $input.all();

const nextFollowup = new Date(Date.now() + 30 * 60 * 1000).toISOString();

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/leads`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'resolution=merge-duplicates,return=representation',
    },
    body: {
      phone, name, destination,
      stage: 'quoted',
      follow_up_count: 0,
      next_followup: nextFollowup,
      paused: false,
      source: 'laila_v4',
    },
    json: true,
  });
} catch(e) {
  console.log(`[SET-FU] failed: ${e.message}`);
}

return $input.all();

// Decision Engine — deterministic routing + AI fallback (no extra prompt layers)
const phone = $json.phone;
const remoteJid = $json.remoteJid;
const text = $json.textContent || $json.text || '';
const isManager = $json.isManager || false;
const intent = $json.conversationIntent || 'general';
const trip = $json.tripFromHistory || null;
const requestedTourDays = $json.requestedTourDays ?? null;
const chatHistory = $json.chatHistory || '';

const SB = String($env.SUPABASE_URL || 'https://xfibcjhshpmqkrhlpsoa.supabase.co').replace(/\/$/, '');
const KEY = $env.SUPABASE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY;
const HDR = { apikey: KEY, Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' };

const HOTEL_ONLY_POLICY =
  'أيوه فهمتك، فندق فقط 👍 حاليًا حجوزاتنا تكون ضمن باقة مع التوصيل، ما نوفر الفندق منفرد.';
const OPS_UNKNOWN = 'أتأكد لك من الفريق وأرجع لك 👍';
const AI_IDENTITY =
  'أنا مساعدة أركاديا بالذكاء الاصطناعي 😊 وإذا احتاج طلبك تدخل موظف من الفريق أحوله لهم.';
const GOODBYE = 'العفو، حياك الله 🌷';
const FALLBACK_HANDOFF =
  'أهلاً 👋 صار خطأ تقني بسيط، جرّب ترسل طلبك مرة ثانية أو تواصل معنا واتساب: https://wa.me/380936582617';

const MONTHS = {
  يناير: 1, فبراير: 2, مارس: 3, ابريل: 4, أبريل: 4, april: 4,
  مايو: 5, يونيو: 6, يوليو: 7, أغسطس: 8, سبتمبر: 9, أكتوبر: 10, اكتوبر: 10,
  نوفمبر: 11, ديسمبر: 12,
};

function arToEnDigits(s) {
  const AR = '٠١٢٣٤٥٦٧٨٩';
  return String(s || '').replace(/[٠-٩]/g, (d) => String(AR.indexOf(d)));
}

function sanitizeReply(s) {
  let t = String(s || '');
  t = t.replace(/\[([^\]]*)\]\((https?:\/\/[^)]+)\)/g, '$2');
  const wa = t.match(/https:\/\/wa\.me\/\d+/g) || [];
  if (wa.length > 1) {
    t = t.replace(/https:\/\/wa\.me\/\d+/g, '').trim() + '\n\n' + wa[0];
  }
  t = t.replace(/\n*‏?إذا تحتاج لأي مساعدة إضافية[^\n]*/gi, '');
  t = t.replace(/\n*‏?(?:هل )?تر(?:غب|يد).*?(?:عرض رسمي|تجهيز العرض)[^\n]*/gi, '');
  return t.trim();
}

function addDays(iso, days) {
  const d = new Date(iso + 'T12:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

function resolveDates(tripCtx, history) {
  const h = arToEnDigits(history || '');
  const m = h.match(/(\d{1,2})\s*(يناير|فبراير|مارس|ابريل|أبريل|مايو|يونيو|يوليو|أغسطس|سبتمبر|أكتوبر|اكتوبر|نوفمبر|ديسمبر)/i);
  if (m) {
    const day = parseInt(m[1], 10);
    const monKey = m[2].replace(/أ/g, 'ا');
    const mon = MONTHS[monKey] || MONTHS[m[2].toLowerCase()];
    if (mon) {
      const year = new Date().getUTCFullYear();
      let checkin = `${year}-${String(mon).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
      if (new Date(checkin) < new Date()) checkin = `${year + 1}-${String(mon).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
      const nights = tripCtx?.nights || 7;
      return { checkin, checkout: addDays(checkin, nights) };
    }
  }
  const checkin = addDays(new Date().toISOString().slice(0, 10), 30);
  const nights = tripCtx?.nights || 7;
  return { checkin, checkout: addDays(checkin, nights) };
}

async function fetchQuoteOptions(tripCtx, mode) {
  if (!KEY || !tripCtx?.city) return null;
  const dates = resolveDates(tripCtx, chatHistory);
  try {
    let data = await this.helpers.httpRequest({
      method: 'POST',
      url: SB + '/rest/v1/rpc/quote_options',
      headers: HDR,
      body: {
        p_city: tripCtx.city,
        p_checkin: dates.checkin,
        p_checkout: dates.checkout,
        p_adults: tripCtx.adults || 2,
        p_rooms: 0,
        p_mode: mode || 'full',
      },
      json: true,
    });
    if (data && data.quote_options) data = data.quote_options;
    if (data && Array.isArray(data.options)) return data;
    return null;
  } catch (e) {
    return null;
  }
}

async function fetchQuotePackage(tripCtx, forceTourDays) {
  if (!KEY || !tripCtx?.city || forceTourDays == null) return null;
  const dates = resolveDates(tripCtx, chatHistory);
  try {
    const data = await this.helpers.httpRequest({
      method: 'POST',
      url: SB + '/rest/v1/rpc/quote_package',
      headers: HDR,
      body: {
        p_city: tripCtx.city,
        p_checkin: dates.checkin,
        p_checkout: dates.checkout,
        p_adults: tripCtx.adults || 2,
        p_rooms: 0,
        p_star: null,
        p_mode: 'recommended',
        p_markup: 0.2,
        p_include_transfer: true,
        p_force_tour_days: forceTourDays,
        p_hotel_tier: 'cheapest',
        p_hotel_name: tripCtx.hotel || null,
      },
      json: true,
    });
    if (data && data.error) return null;
    if (data && data.final_price_usd != null) return data;
    return null;
  } catch (e) {
    return null;
  }
}

async function persistPackagePrefs(tripCtx, tourDays, price, hotelName) {
  if (!KEY || !phone) return;
  const notes = [
    tripCtx.city ? `city=${tripCtx.city}` : '',
    tripCtx.nights != null ? `nights=${tripCtx.nights}` : '',
    `tour_days=${tourDays}`,
    hotelName ? `hotel=${hotelName}` : tripCtx.hotel ? `hotel=${tripCtx.hotel}` : '',
    `last_price=${price}`,
  ]
    .filter(Boolean)
    .join(';');
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: SB + '/rest/v1/leads?phone=eq.' + phone,
      headers: { ...HDR, Prefer: 'return=minimal' },
      body: { notes, updated_at: new Date().toISOString() },
    });
  } catch (e) {}
}

function pickQuoteOption(quoteData, tripCtx) {
  const opts = quoteData.options || [];
  if (tripCtx?.last_price) {
    const hit = opts.find((o) => String(o.price_usd) === String(tripCtx.last_price));
    if (hit) return hit;
  }
  if (tripCtx?.tour_days != null) {
    const byTour = opts.find((o) => o.tour_days === tripCtx.tour_days);
    if (byTour) return byTour;
  }
  return opts.find((o) => /basic|أساس/i.test(String(o.tier || ''))) || opts[0];
}

function currentTourDays(quoteData, option, tripCtx) {
  if (tripCtx?.tour_days != null) return tripCtx.tour_days;
  return option?.tour_days ?? quoteData?.nights;
}

function formatPackageExplain(quoteData, option, tripCtx) {
  const nights = quoteData.nights;
  const totalDays = nights + 1;
  const tourDays = currentTourDays(quoteData, option, tripCtx);
  return `الرحلة ${totalDays} أيام / ${nights} ليالي 👍 العرض الحالي فيه ${tourDays} أيام جولات — ونقدر نزيدها أو نقللها على راحتك.`;
}

function formatTourFlexibility(quoteData, option, tripCtx) {
  const tourDays = currentTourDays(quoteData, option, tripCtx);
  const next = tourDays + 1;
  return `العرض الحالي فيه ${tourDays} أيام جولات، بس عادي نقدر نعدله على راحتك 👍 إذا تحب ${next} جولات أضيف لك يوم جولة وأحسب لك السعر الجديد، وإذا تحب أقل نقدر نقللها برضه.`;
}

function formatTourModify(pkg, tourDays, adults) {
  const pax = adults || 2;
  const paxLabel = pax === 2 ? 'شخصين' : `${pax} أشخاص`;
  const tourLabel = tourDays === 2 ? 'جولتين' : `${tourDays} أيام جولات`;
  return `تمام 👍 خليتها ${tourLabel}. السعر بعد التعديل صار ${pkg.final_price_usd} دولار لـ${paxLabel}.`;
}

function formatQuoteReply(tripCtx, quoteData, intro) {
  const opts = quoteData.options || [];
  const basic = opts.find((r) => /basic|أساس|eco/i.test(String(r.tier || ''))) || opts[0];
  const rec = opts.find((r) => /recommend|موص/i.test(String(r.tier || ''))) || opts[1] || opts[0];
  const lines = [intro || 'تمام، خليني أشوف لك خيارات أوفر 👍', ''];
  if (basic) lines.push(`1️⃣ أساسية — ${basic.hotel || 'فندق'} — ${basic.price_usd} دولار`);
  if (rec && rec !== basic) lines.push(`2️⃣ موصى بها — ${rec.hotel || 'فندق'} — ${rec.price_usd} دولار`);
  lines.push('', 'إذا يناسبك خبرني 👍');
  return lines.join('\n');
}

async function flagNeedsHuman() {
  if (!KEY || !phone) return;
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: SB + '/rest/v1/leads?phone=eq.' + phone,
      headers: { ...HDR, Prefer: 'return=minimal' },
      body: { needs_human: true, updated_at: new Date().toISOString() },
    });
  } catch (e) {}
}

let response = '';
let routedBy = 'ai_agent';

if (intent === 'goodbye') {
  response = GOODBYE;
  routedBy = 'deterministic:goodbye';
} else if (intent === 'ai_identity') {
  response = AI_IDENTITY;
  routedBy = 'deterministic:ai_identity';
} else if (intent === 'ops_unknown') {
  response = OPS_UNKNOWN;
  routedBy = 'deterministic:ops_unknown';
  await flagNeedsHuman.call(this);
} else if (intent === 'hotel_only') {
  response = HOTEL_ONLY_POLICY;
  routedBy = 'deterministic:hotel_only_policy';
} else if (intent === 'returning_customer' && trip) {
  const bits = [];
  if (trip.destination) bits.push(trip.destination);
  if (trip.nights) bits.push(trip.nights + ' ليالي');
  if (trip.adults) bits.push(trip.adults + ' أشخاص');
  response = `تمام، عندي طلبك: ${bits.join('، ') || 'طلبك السابق'} 👍`;
  if (trip.last_price) response += `\nآخر عرض كان ${trip.last_price} دولار — تبي أرسله لك مرة ثانية؟`;
  else response += '\nتبي أرسل لك آخر عرض؟';
  routedBy = 'deterministic:returning_customer';
} else if (intent === 'package_tour_modify' && trip?.city && requestedTourDays != null) {
  routedBy = 'deterministic:package_tour_modify';
  const pkg = await fetchQuotePackage.call(this, trip, requestedTourDays);
  if (pkg) {
    const hotelName = pkg.hotel?.name || trip.hotel || null;
    response = formatTourModify(pkg, requestedTourDays, trip.adults);
    await persistPackagePrefs.call(this, trip, requestedTourDays, pkg.final_price_usd, hotelName);
  } else {
    response = OPS_UNKNOWN;
  }
} else if ((intent === 'package_tour_flexibility' || intent === 'package_composition') && trip?.city) {
  routedBy = 'deterministic:' + intent;
  const quoteData = await fetchQuoteOptions.call(this, trip, 'full');
  if (quoteData) {
    const option = pickQuoteOption(quoteData, trip);
    if (option) {
      response =
        intent === 'package_tour_flexibility'
          ? formatTourFlexibility(quoteData, option, trip)
          : formatPackageExplain(quoteData, option, trip);
    }
  }
  if (!response) response = OPS_UNKNOWN;
} else if (intent === 'price_objection') {
  routedBy = 'deterministic:pricing_engine';
  const quoteData = await fetchQuoteOptions.call(this, trip, 'no_tours');
  if (quoteData) response = formatQuoteReply(trip, quoteData, 'تمام، خليني أشوف لك خيارات أوفر 👍');
  if (!response) {
    const quoteFull = await fetchQuoteOptions.call(this, trip, 'full');
    if (quoteFull) response = formatQuoteReply(trip, quoteFull, 'تمام، خليني أشوف لك خيارات أوفر 👍');
  }
}

if (!response) {
  const payload = {
    action: 'sendMessage',
    sessionId: String(phone || 'wa'),
    chatInput: text,
    leadContext: $json.leadStateSummary || '',
    chatHistory,
    managerInstructions: $json.managerInstructions || '',
    context: $json.context || '',
    conversationHints: ($json.conversationHints || []).join('\n'),
    customerLanguage: $json.customerLanguage || 'ar',
  };
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://n8n.arcadia-tour.cloud/webhook/cc004272-5e46-4e5c-be6d-ba84fdf35258/chat',
      body: payload,
      json: true,
      timeout: 90000,
    });
    if (typeof res === 'string') {
      try { response = JSON.parse(res).output; } catch (e) { response = res; }
    } else {
      response = (res && (res.output || res.text || res.response)) || '';
    }
  } catch (e) {
    response = '';
  }
  routedBy = 'ai_agent';
}

response = sanitizeReply(response);

if (intent === 'price_objection' && /ما قدرت أكمل طلبك|تواصل مباشرة/.test(response) && trip?.city) {
  const quoteData = await fetchQuoteOptions.call(this, trip, 'no_tours');
  if (quoteData) {
    response = formatQuoteReply(trip, quoteData, 'تمام، خليني أشوف لك خيارات أوفر 👍');
    routedBy = 'deterministic:pricing_engine_retry';
  }
}

if (!response) response = FALLBACK_HANDOFF;

const followup = /دولار|\$|💵/.test(response);
return [{ json: { phone, remoteJid, response, isManager, followup, routedBy } }];

// Phase1 observability — parse Decision Engine response (no pricing logic change)
const de = $input.first().json;
const ctx = $('Arcadia - Phase1 Inbound Pipeline').first()?.json || {};
const response = String(de.response || '');
const priceUsd = response.match(/\$[\d,]+/)?.[0] || response.match(/([\d,]{3,})\s*USD/i)?.[0] || null;
const manualPath = /no_hotel|يدوي|human|موظف|فريق/i.test(response);
const hasPrice = !!priceUsd || /\$[\d,]{2,}|USD\s*[\d,]+|دولار/.test(response);
return [{ json: {
  phone: de.phone,
  remoteJid: de.remoteJid,
  response: de.response,
  isManager: de.isManager,
  followup: de.followup,
  lead_id: ctx.lead_id,
  customer_id: ctx.customer_id,
  channel: ctx.phase1?.channel || 'whatsapp',
  action_type: 'get_price',
  status: manualPath && !hasPrice ? 'failed' : (hasPrice ? 'success' : 'failed'),
  output_summary: (priceUsd || response).slice(0, 500),
  input_summary: String(ctx.phase1?.message_text || '').slice(0, 500),
  metadata: { phase1: 'pricing_observability', source: 'decision_engine_response' }
}}];

// Phase1 — normalize inbound (no prompt / stage changes)
const j = $input.first().json;
const raw = $('WhatsApp Webhook').first()?.json || $('Telegram Trigger').first()?.json || {};
const body = raw.body || raw;
const data = body.data || body;
const key = data.key || {};
const waMsg = body.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
const tgMsg = raw.message || body.message;
const msg = waMsg || tgMsg || body.messages?.[0] || {};
const phone = String(
  j.phone
  || key.remoteJid?.replace('@s.whatsapp.net', '').replace('@g.us', '')
  || msg.from
  || tgMsg?.chat?.id
  || body.from?.id
  || j.chat_id
  || ''
).trim();
const providerMessageId = key.id ? String(key.id)
  : (waMsg?.id ? String(waMsg.id)
  : (tgMsg?.message_id != null ? String(tgMsg.message_id) : (j.provider_message_id || null)));
const channel = key.remoteJid || waMsg?.id ? 'whatsapp' : (tgMsg ? 'telegram' : (j.channel || 'whatsapp'));
const text = j.textContent || j.text || msg.text?.body || msg.body || tgMsg?.text || '';
const ALLOWED = new Set(['text','image','audio','document','location','video','sticker','unknown']);
const TYPE_MAP = { conversation: 'text', extendedTextMessage: 'text', audioMessage: 'audio', imageMessage: 'image', documentMessage: 'document', videoMessage: 'video', stickerMessage: 'sticker' };
const rawType = data.messageType || msg.type || (tgMsg?.photo ? 'image' : 'text');
const messageType = TYPE_MAP[rawType] || (ALLOWED.has(rawType) ? rawType : 'unknown');
return [{ json: {
  ...j,
  phase1: {
    phone,
    provider_message_id: providerMessageId,
    channel,
    message_text: text,
    message_type: messageType,
    metadata: { raw_channel: channel, normalized_at: new Date().toISOString(), source: 'phase1_normalize' }
  }
}}];

// Phase1 — prepare outbound log AFTER successful send only
function extractOutboundText(val) {
  if (val == null) return null;
  if (typeof val === 'string') { const s = val.trim(); return s || null; }
  if (typeof val === 'object') {
    return val.conversation || val.extendedTextMessage?.text || val.text || null;
  }
  return null;
}
const send = $input.first().json;
const de = $('Decision Engine').first()?.json || {};
const ctx = $('Arcadia - Phase1 Inbound Pipeline').first()?.json
  || $('Phase1 IF Proceed (not duplicate)').first()?.json
  || {};
const messageText = extractOutboundText(send.text)
  || extractOutboundText(send.message)
  || extractOutboundText(send.body?.text)
  || extractOutboundText(send.body)
  || (typeof send.output === 'string' ? send.output.trim() : null)
  || (typeof send.reply === 'string' ? send.reply.trim() : null)
  || (typeof de.response === 'string' ? de.response.trim() : null);
return [{ json: {
  lead_id: ctx.lead_id,
  customer_id: ctx.customer_id,
  conversation_id: ctx.conversation_id,
  channel: ctx.phase1?.channel || ctx.channel,
  message_text: messageText,
  provider_message_id: send.message_id || send.messages?.[0]?.id || send.key?.id || null,
  metadata: { phase1: 'outbound_after_send_success' }
}}];
